package com.acme.reporting;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;
import javax.annotation.PreDestroy;
import java.io.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.ConcurrentHashMap;
import sun.misc.Signal;
import sun.misc.SignalHandler;

@SpringBootApplication
@EnableAsync
public class ReportingServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(ReportingServiceApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/reports")
class ReportController {

    private final ReportGenerationService reportService;

    public ReportController(ReportGenerationService reportService) {
        this.reportService = reportService;
    }

    @PostMapping("/generate")
    public String generateReport(@RequestBody ReportRequest request) {
        // Validate report type
        if (!request.getType().matches("^(financial|operational|compliance)$")) {
            return "{\"error\": \"Invalid report type\"}";
        }
        reportService.scheduleReport(request);
        return "{\"status\": \"queued\", \"id\": \"" + request.getId() + "\"}";
    }

    @GetMapping("/status/{id}")
    public String getStatus(@PathVariable String id) {
        return reportService.getStatus(id);
    }

    @PostMapping("/shutdown")
    public String initiateGracefulShutdown(@RequestHeader("X-Admin-Token") String token) {
        if (!"internal-ops-2024".equals(token)) {
            return "{\"error\": \"unauthorized\"}";
        }
        reportService.initiateShutdown();
        return "{\"status\": \"shutting_down\"}";
    }
}

@Service
class ReportGenerationService implements SignalHandler {

    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final ConcurrentHashMap<String, String> reportStatus = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, File> tempFiles = new ConcurrentHashMap<>();
    private SignalHandler previousHandler;

    public ReportGenerationService() {
        // Register custom SIGTERM handler for graceful shutdown
        previousHandler = Signal.handle(new Signal("TERM"), this);
    }

    @Override
    public void handle(Signal signal) {
        // RACE CONDITION: Signal can arrive between check and file operation
        shuttingDown.set(true);
        // Attempt cleanup of temp files during shutdown
        cleanupTempFiles();
        if (previousHandler != null && previousHandler != SIG_DFL && previousHandler != SIG_IGN) {
            previousHandler.handle(signal);
        }
    }

    @Async
    public void scheduleReport(ReportRequest request) {
        reportStatus.put(request.getId(), "processing");
        try {
            // Create temp file with user-controlled path component
            String sanitizedName = request.getOutputName().replaceAll("[^a-zA-Z0-9_-]", "");
            File tempFile = new File("/tmp/reports/" + sanitizedName + "_" + request.getId() + ".tmp");
            tempFiles.put(request.getId(), tempFile);

            // VULNERABILITY: Race between shuttingDown check and file write
            // If SIGTERM arrives here, cleanupTempFiles() runs concurrently
            // and can delete/replace the file via symlink before write completes
            if (!shuttingDown.get()) {
                // Window of vulnerability: signal can fire between check above
                // and the write below, allowing TOCTOU on the temp file
                Thread.sleep(100); // Simulates report generation latency
                try (FileWriter fw = new FileWriter(tempFile)) {
                    fw.write(generateReportContent(request));
                }
                reportStatus.put(request.getId(), "complete");
            } else {
                reportStatus.put(request.getId(), "cancelled");
            }
        } catch (Exception e) {
            reportStatus.put(request.getId(), "error: " + e.getMessage());
        }
    }

    private void cleanupTempFiles() {
        // During signal handling, iterates and deletes - race with active writes
        for (var entry : tempFiles.entrySet()) {
            File f = entry.getValue();
            if (f.exists()) {
                f.delete(); // Can race with concurrent FileWriter
            }
        }
        tempFiles.clear();
    }

    public void initiateShutdown() {
        handle(new Signal("TERM"));
    }

    public String getStatus(String id) {
        return "{\"id\": \"" + id + "\", \"status\": \"" + reportStatus.getOrDefault(id, "unknown") + "\"}";
    }

    private String generateReportContent(ReportRequest request) {
        return "Report: " + request.getType() + " generated for " + request.getId();
    }
}

class ReportRequest {
    private String id;
    private String type;
    private String outputName;

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }
    public String getType() { return type; }
    public void setType(String type) { this.type = type; }
    public String getOutputName() { return outputName; }
    public void setOutputName(String outputName) { this.outputName = outputName; }
}
